import { createHmac, timingSafeEqual } from "node:crypto";

function decodeBase64Url(value) {
  return Buffer.from(value, "base64url");
}

function decodeJsonPart(value) {
  return JSON.parse(decodeBase64Url(value).toString("utf8"));
}

function validateVerificationSignature({
  signature,
  memberIdentifier,
  companyJobCode,
  developerApplications,
  replayCache,
  supportedVersions = new Set(["1"]),
  clockSkewSeconds = 60,
}) {
  const parts = signature.split(".");
  if (parts.length !== 3) {
    throw new Error("Invalid compact JWS format");
  }

  const [encodedHeader, encodedPayload, encodedMac] = parts;
  const header = decodeJsonPart(encodedHeader);
  const payload = decodeJsonPart(encodedPayload);

  if (header.alg !== "HS256" || typeof header.kid !== "string") {
    throw new Error("Unsupported algorithm or missing key identifier");
  }

  // Look up the secret by kid. Keep current and previous secrets during rotation.
  const application = developerApplications.get(header.kid);
  if (!application || !application.currentSecret) {
    throw new Error("Unknown developer application");
  }

  const signingInput = `${encodedHeader}.${encodedPayload}`;
  const receivedMac = decodeBase64Url(encodedMac);
  const validSecret = [application.currentSecret, application.previousSecret]
    .filter(Boolean)
    .find((secret) => {
      const expectedMac = createHmac("sha256", secret)
        .update(signingInput)
        .digest();
      return (
        receivedMac.length === expectedMac.length &&
        timingSafeEqual(receivedMac, expectedMac)
      );
    });

  if (!validSecret) {
    throw new Error("Invalid JWS signature");
  }

  const now = Math.floor(Date.now() / 1000);
  if (
    payload.sub !== memberIdentifier ||
    payload.job !== companyJobCode ||
    !supportedVersions.has(payload.ver) ||
    typeof payload.exp !== "number" ||
    payload.exp <= now ||
    typeof payload.iat !== "number" ||
    payload.iat > now + clockSkewSeconds ||
    typeof payload.jti !== "string" ||
    replayCache.has(payload.jti)
  ) {
    throw new Error("Invalid verification claims");
  }

  // Mark the nonce as used only after signature and claim validation succeeds.
  replayCache.add(payload.jti, payload.exp - now);

  return {
    verifications: payload.verifications,
    verifiedDetails: payload.verifiedDetails,
  };
}

// Example inputs from your server-side application.
const verificationData = {
  verifications: [],
  signature: "******",
};

const verified = validateVerificationSignature({
  signature: verificationData.signature,
  memberIdentifier: submission.memberIdentifier,
  companyJobCode: submission.companyJobCode,
  developerApplications: new Map([
    ["12345", { currentSecret: process.env.CUSTOMER_CLIENT_SECRET }],
  ]),
  replayCache,
});

// Store and display only this validated data.
console.log(verified.verifications, verified.verifiedDetails);

